        public async Task Initialize()
        {
            InitGameSettings();
            InitSerializable();
            LogInformations();
            await LoadManagersInit();
            initialized = true;
            Scene.Init();
        }
        public void UpdateManagerFixed()
        {
        }
        public bool IsMobile()
        {
#if UNITY_EDITOR
            switch (platformMode)
            {
                case PlatformMode.Mobile:
                    return true;
                case PlatformMode.Standalone:
                    return false;
            }
#endif

#if UNITY_ANDROID || UNITY_IOS
            return true;
#else
            return false;
#endif
        }
        public bool UseMobileLayout()
        {
            if (initialized)
            {
                var screenLayout = OptionsManager.GetScreenLayout();
                if (screenLayout != ScreenLayouts.AUTO)
                {
                    return screenLayout == ScreenLayouts.MOBILE;
                }
            }
            return IsMobile();
        }
        public TaskPipeline? GetLoadPipeline()
